//! Vanilla 26.2's advancement tree, as data.
//!
//! Generated by walking the 26.2 data pack's own advancement JSONs at
//! `.cache/mc/26.2/src/data/minecraft/advancement/**` — every file outside
//! `recipes/` that carries a `display` block, which is exactly the set vanilla's
//! own `AdvancementsScreen` builds widgets for: **126 advancements over 5 roots**.
//! (The other ~1560 files under `recipes/` are recipe-unlock advancements with no
//! `display`; vanilla's `AdvancementNode` skips them for layout and so do we.)
//!
//! ## What is here and what is not
//!
//! `title`/`description` are the JSON's own `translate` keys, resolved at draw
//! time through the live language table — all 252 of them verified present in
//! `client.jar`'s `assets/minecraft/lang/en_us.json`. Every `icon` id was
//! cross-checked against `lodestone-data`'s generated `ITEM_NAMES`, zero
//! mismatches.
//!
//! **There is no `x`/`y` here, and that is not an omission.** 26.2's advancement
//! JSON carries no position: `DisplayInfo`'s `x`/`y` are computed server-side by
//! `TreeNodePosition` and only ever appear on the wire. So the layout is ours to
//! run — see [`super::advancement_tree`], which ports that algorithm — and there
//! is nothing on disk to verify a position against.
//!
//! `criteria` and `requirements` are not modelled beyond
//! [`Advancement::requirement_count`], the denominator vanilla's
//! `AdvancementProgress::getProgressText` divides by. Nothing decodes
//! `UPDATE_ADVANCEMENTS` yet, so every advancement draws unobtained; the count is
//! here so the progress readout needs no data change when it lands.
//!
//! ## How to change it
//!
//! Re-run the extraction against a newer data pack. There is no generator script
//! checked in (the source is `.cache`, not repo state), so record any new
//! extraction the same way: verify every icon against `ITEM_NAMES` and every
//! translation key against `en_us.json` before committing, since a wrong icon id
//! degrades to an empty frame and a wrong key draws the raw key.

/// Which of vanilla's three `AdvancementType`s an advancement is — the frame
/// shape drawn around its icon, and the title-box colour.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AdvancementFrame {
    /// The ordinary square frame.
    Task,
    /// The rounded "goal" frame.
    Goal,
    /// The spiked "challenge" frame.
    Challenge,
}

impl AdvancementFrame {
    /// The `advancements/{task,goal,challenge}_frame_{obtained,unobtained}`
    /// sprite for this frame — `AdvancementWidgetType.frameSprite`.
    #[must_use]
    pub fn frame_sprite(self, obtained: bool) -> &'static str {
        match (self, obtained) {
            (Self::Task, false) => "advancements/task_frame_unobtained",
            (Self::Task, true) => "advancements/task_frame_obtained",
            (Self::Goal, false) => "advancements/goal_frame_unobtained",
            (Self::Goal, true) => "advancements/goal_frame_obtained",
            (Self::Challenge, false) => "advancements/challenge_frame_unobtained",
            (Self::Challenge, true) => "advancements/challenge_frame_obtained",
        }
    }
}

/// One advancement, as the datapack declares it.
#[derive(Debug, Clone, Copy)]
pub struct Advancement {
    /// Its registry id, e.g. `minecraft:story/mine_stone`.
    pub id: &'static str,
    /// Its parent's id, or `None` for one of the five roots.
    pub parent: Option<&'static str>,
    /// `display.title`'s translation key.
    pub title: &'static str,
    /// `display.description`'s translation key.
    pub description: &'static str,
    /// `display.icon.id`.
    pub icon: &'static str,
    /// `display.frame`, defaulting to `task` when the JSON omits it.
    pub frame: AdvancementFrame,
    /// `display.hidden` — vanilla draws neither the widget nor its connector
    /// until it is obtained.
    pub hidden: bool,
    /// `display.background`, on the five roots only: the tiled texture behind
    /// that tab's tree.
    pub background: Option<&'static str>,
    /// How many `requirements` groups it has — the denominator of vanilla's
    /// `"%s/%s"` progress readout. `1` for the great majority.
    pub requirement_count: u32,
    /// `en_us.json`'s own value for [`title`](Self::title), for a run with no
    /// language table. The same fallback shape the creative screen's tab titles
    /// use; the live table always wins.
    pub title_en: &'static str,
    /// See [`title_en`](Self::title_en).
    pub description_en: &'static str,
}

