#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_census_matches_the_data_pack() {
        // 126 advancements with a `display` block, 5 roots — the counts the
        // extraction reported, pinned so a partial re-extraction is loud.
        assert_eq!(ADVANCEMENTS.len(), 126);
        assert_eq!(ADVANCEMENTS.iter().filter(|a| a.parent.is_none()).count(), 5);
        for root in ADVANCEMENTS.iter().filter(|a| a.parent.is_none()) {
            assert!(root.background.is_some(), "{} has no background", root.id);
        }
    }

    #[test]
    fn every_parent_resolves_and_precedes_its_children() {
        let mut seen: Vec<&str> = Vec::new();
        for a in ADVANCEMENTS {
            if let Some(parent) = a.parent {
                assert!(seen.contains(&parent), "{} precedes its parent {parent}", a.id);
            }
            seen.push(a.id);
        }
    }

    #[test]
    fn every_id_is_well_formed() {
        for a in ADVANCEMENTS {
            assert!(a.id.starts_with("minecraft:"), "{}", a.id);
            assert!(a.icon.starts_with("minecraft:"), "{}", a.icon);
            assert!(a.title.starts_with("advancements."), "{}", a.title);
            assert!(a.description.starts_with("advancements."), "{}", a.description);
            assert!(!a.title_en.is_empty() && !a.description_en.is_empty(), "{}", a.id);
        }
    }
}
